      --bg: #042f2e;\n      --surface: #0a3d3a;\n      --border: rgba(255, 255, 255, 0.08);\n      --text: #ccfbf1;\n      --text-dim: #5eead4;\n\n      --primary: #2dd4bf;\n      --primary-dim: rgba(45, 212, 191, 0.14);\n      --secondary: #38bdf8;\n      --tertiary: #fbbf24;\n      --danger: #f87171;\n    }\n  }\n\n  /* ============ RESET + BASE ============ */\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n\n  body {\n    background-color: var(--bg);\n    background-image: radial-gradient(circle, var(--border) 1px, transparent 1px);\n    background-size: 24px 24px;\n    color: var(--text);\n    font-family: var(--font-body);\n    padding: 40px;\n    min-height: 100vh;\n  }\n\n  /* ============ ANIMATION ============ */\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(12px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  .animate {\n    animation: fadeUp 0.4s ease-out both;\n    animation-delay: calc(var(--i, 0) * 0.06s);\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n      animation-duration: 0.01ms !important;\n      animation-delay: 0ms !important;\n      transition-duration: 0.01ms !important;\n    }\n  }\n\n  /* ============ LAYOUT ============ */\n  .container {\n    max-width: 1000px;\n    margin: 0 auto;\n  }\n\n  h1 {\n    font-size: 38px;\n    font-weight: 700;\n    letter-spacing: -1px;\n    margin-bottom: 6px;\n    text-wrap: balance;\n  }\n\n  .subtitle {\n    color: var(--text-dim);\n    font-family: var(--font-mono);\n    font-size: 12px;\n    margin-bottom: 32px;\n  }\n\n  .description {\n    font-size: 14px;\n    line-height: 1.7;\n    color: var(--text-dim);\n    margin-bottom: 24px;\n    max-width: 700px;\n  }\n\n  .description code {\n    font-family: var(--font-mono);\n    font-size: 12px;\n    background: var(--primary-dim);\n    color: var(--primary);\n    padding: 1px 5px;\n    border-radius: 3px;\n  }\n\n  /* ============ MERMAID CONTAINER ============ */\n  .mermaid-wrap {\n    position: relative;\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    padding: 32px 24px;\n    overflow: auto;\n    margin-bottom: 24px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 400px;\n  }\n\n  .zoom-controls {\n    position: absolute;\n    top: 8px;\n    right: 8px;\n    display: flex;\n    gap: 2px;\n    z-index: 10;\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: 6px;\n    padding: 2px;\n  }\n\n  .zoom-controls button {\n    width: 28px;\n    height: 28px;\n    border: none;\n    background: transparent;\n    color: var(--text-dim);\n    font-family: var(--font-mono);\n    font-size: 14px;\n    cursor: pointer;\n    border-radius: 4px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: background 0.15s ease, color 0.15s ease;\n  }\n\n  .zoom-controls button:hover {\n    background: var(--border);\n    color: var(--text);\n  }\n\n  .mermaid-wrap { cursor: grab; }\n  .mermaid-wrap.is-panning { cursor: grabbing; user-select: none; }\n\n  /* ============ MULTI-DIAGRAM STRUCTURE ============ */\n  .diagram-shell {\n    position: relative;\n  }\n\n  .diagram-shell__hint {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    color: var(--text-dim);\n    margin-bottom: 8px;\n    opacity: 0.7;\n  }\n\n  .mermaid-viewport {\n    position: relative;\n    overflow: hidden;\n    width: 100%;\n    height: 100%;\n    min-height: 300px;\n  }\n\n  .mermaid-canvas {\n    position: absolute;\n    top: 0;\n    left: 0;\n  }\n\n  .zoom-label {\n    font-family: var(--font-mono);\n    font-size: 10px;\n    color: var(--text-dim);\n    padding: 0 6px;\n    white-space: nowrap;\n  }\n\n  /* ============ MERMAID SVG OVERRIDES ============ */\n  .mermaid .nodeLabel {\n    font-family: var(--font-body) !important;\n    font-size: 16px !important;\n  }\n\n  .mermaid .edgeLabel {\n    font-family: var(--font-mono) !important;\n    font-size: 13px !important;\n  }\n\n  .mermaid .node rect,\n  .mermaid .node circle,\n  .mermaid .node polygon {\n    stroke-width: 1.5px !important;\n  }\n\n  .mermaid .edge-pattern-solid {\n    stroke-width: 1.5px !important;\n  }\n\n  /* ============ LEGEND ============ */\n  .legend {\n    display: flex;\n    gap: 20px;\n    flex-wrap: wrap;\n  }\n\n  .legend-item {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    font-family: var(--font-mono);\n    font-size: 11px;\n    color: var(--text-dim);\n  }\n\n  .legend-swatch {\n    width: 12px;\n    height: 12px;\n    border-radius: 3px;\n  }\n\n  /* ============ CALLOUT ============ */\n  .callout {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-left: 3px solid var(--primary);\n    border-radius: 0 10px 10px 0;\n    padding: 16px 20px;\n    font-size: 13px;\n    line-height: 1.6;\n    color: var(--text-dim);\n    margin-top: 24px;\n  }\n\n  .callout strong { color: var(--text); }\n\n  .callout code {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    background: var(--primary-dim);\n    color: var(--primary);\n    padding: 1px 5px;\n    border-radius: 3px;\n  }\n\n  /* ============ RESPONSIVE ============ */\n  @media (max-width: 768px) {\n    body { padding: 16px; }\n    h1 { font-size: 22px; }\n    .mermaid-wrap { padding: 16px 12px; }\n  }\n</style>\n</head>\n<body>\n\n<div class=\"container\">\n\n  <h1 class=\"animate\" style=\"--i:0\">CI/CD Pipeline</h1>\n  <p class=\"subtitle animate\" style=\"--i:1\">github actions &rarr; staging &rarr; production</p>\n\n  <p class=\"description animate\" style=\"--i:2\">\n    Every push to <code>main</code> triggers the full pipeline. Tests and linting run in parallel,\n    then the build step produces a Docker image. Staging deploys automatically; production requires\n    manual approval via a GitHub environment gate.\n  </p>\n\n  <section class=\"diagram-shell animate\" style=\"--i:3\">\n    <p class=\"diagram-shell__hint\">\n      Ctrl/Cmd + wheel to zoom. Scroll to pan. Drag to pan when zoomed. Double-click to fit.\n    </p>\n    <div class=\"mermaid-wrap\">\n      <div class=\"zoom-controls\">\n        <button type=\"button\" data-action=\"zoom-in\" title=\"Zoom in\">+</button>\n        <button type=\"button\" data-action=\"zoom-out\" title=\"Zoom out\">&minus;</button>\n        <button type=\"button\" data-action=\"zoom-fit\" title=\"Smart fit\">&#8634;</button>\n        <button type=\"button\" data-action=\"zoom-one\" title=\"1:1 zoom\">1:1</button>\n        <button type=\"button\" data-action=\"zoom-expand\" title=\"Open full size\">&#x26F6;</button>\n        <span class=\"zoom-label\">Loading...</span>\n      </div>\n      <div class=\"mermaid-viewport\">\n        <div class=\"mermaid mermaid-canvas\"></div>\n      </div>\n    </div>\n    <script type=\"text/plain\" class=\"diagram-source\">\n      graph TD\n        A[Push to main] --> B{Branch?}\n        B -->|main| C[Run Tests]\n        B -->|feature| I[Run Tests]\n        I --> J[Preview Deploy]\n        C --> D[Lint + Type Check]\n        C --> E[Unit Tests]\n        C --> F[Integration Tests]\n        D --> G[Build Docker Image]\n        E --> G\n        F --> G\n        G --> H[Deploy to Staging]\n        H --> K{Smoke Tests Pass?}\n        K -->|Yes| L[Manual Approval]\n        K -->|No| M[Alert + Rollback]\n        L --> N[Deploy to Production]\n        N --> O[Health Check]\n        O --> P[Done]\n    </script>\n  </section>\n\n  <div class=\"legend animate\" style=\"--i:4\">\n    <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:var(--primary)\"></div> Automated step</div>\n    <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:var(--tertiary)\"></div> Decision gate</div>\n    <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:var(--danger)\"></div> Failure path</div>\n    <div class=\"legend-item\"><div class=\"legend-swatch\" style=\"background:var(--secondary)\"></div> Success</div>\n  </div>\n\n  <div class=\"callout animate\" style=\"--i:5\">\n    <strong>ELK layout.</strong> The <code>layout: 'elk'</code> engine provides better node positioning\n    for complex graphs — it requires the separate <code>@mermaid-js/layout-elk</code> package (imported above).\n    Without it, Mermaid silently falls back to dagre.\n  </div>\n\n</div>\n\n<script type=\"module\">\n  import mermaid from '/app/libs/mermaid.esm.min.mjs';\n  import elkLayouts from '/app/libs/mermaid-layout-elk.esm.min.mjs';\n\n  const config = {\n    fitPadding: 28,\n    minHeight: 360,\n    maxHeightPx: 960,\n    maxHeightVh: 0.84,\n    maxInitialZoom: 1.8,\n    minZoom: 0.08,\n    maxZoom: 6.5,\n    zoomStep: 0.14,\n    readabilityFloor: 0.58\n  };\n\n  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));\n\n  let activeDrag = null;\n\n  addEventListener('mousemove', (e) => activeDrag?.onMove(e));\n  addEventListener('mouseup', () => {\n    activeDrag?.onEnd();\n    activeDrag = null;\n  });\n\n  const isDark = matchMedia('(prefers-color-scheme: dark)').matches;\n\n  mermaid.registerLayoutLoaders(elkLayouts);\n  mermaid.initialize({\n    startOnLoad: false,\n    theme: 'base',\n    look: 'classic',\n    layout: 'elk',\n    themeVariables: {\n      fontFamily: \"'Bricolage Grotesque', system-ui, sans-serif\",\n      fontSize: '16px',\n      primaryColor: isDark ? '#115e59' : '#ccfbf1',\n      primaryBorderColor: isDark ? '#2dd4bf' : '#0d9488',\n      primaryTextColor: isDark ? '#ccfbf1' : '#134e4a',\n      secondaryColor: isDark ? '#0c4a6e' : '#e0f2fe',\n      secondaryBorderColor: isDark ? '#38bdf8' : '#0369a1',\n      secondaryTextColor: isDark ? '#ccfbf1' : '#134e4a',\n      tertiaryColor: isDark ? '#2e2618' : '#fffbeb',\n      tertiaryBorderColor: isDark ? '#fbbf24' : '#d97706',\n      tertiaryTextColor: isDark ? '#ccfbf1' : '#134e4a',\n      lineColor: isDark ? '